questions.question:
Predict the output order.

console.log('A');
setTimeout(() => {
  console.log('B');
  Promise.resolve().then(() => console.log('C'));
}, 0);
Promise.resolve().then(() => {
  console.log('D');
  setTimeout(() => console.log('E'), 0);
});
console.log('F');

Explain the output and why the nested microtask runs before the timer.

Promise.resolve().then(() => {
  console.log('then 1');
  queueMicrotask(() => console.log('inner micro'));
  setTimeout(() => console.log('timer'), 0);
});
Promise.resolve().then(() => console.log('then 2'));

