questions.answer:
function debounce(fn, wait) {
  let timer = null;

  function debounced(...args) {
    clearTimeout(timer);
    timer = setTimeout(() => {
      timer = null;
      fn.apply(this, args);
    }, wait);
  }

  debounced.cancel = () => {
    clearTimeout(timer);
    timer = null;
  };

  return debounced;
}

const search = debounce((term) => console.log("search:", term), 100);
search("Kak");
search("Kakade");
// after ~100 ms: search: Kakade

Each call cancels the pending timer and schedules a new one, so only the last call in a burst survives. The closure keeps the timer id private. fn.apply(this, args) preserves the caller's this and the latest arguments — important when the debounced function is an object method or an event handler. cancel() is useful on unmount or when a new query supersedes the old one. Debounce is for 'wait until quiet'; throttle is for 'at most once per interval'.

